package eit_image_availability_coordinator.EIT_Image_Availability_Coordinator

import org.sireum._
import art.Art
import eit_image_availability_coordinator._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait FaultComposition_coordination_fault_composition_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.EITImageAvailabilitySystem_Instance_coordination_fault_composition)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.EITImageAvailabilitySystem_Instance_coordination_fault_composition)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.EITImageAvailabilitySystem_Instance_coordination_fault_composition)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.EITImageAvailabilitySystem_Instance_coordination_fault_composition)
  }

  /** helper function to set the values of all input ports.
   * @param imageFacts payload for data port imageFacts
   * @param reviewFacts payload for data port reviewFacts
   * @param contextFacts payload for data port contextFacts
   * @param serviceFacts payload for data port serviceFacts
   */
  def put_concrete_inputs(imageFacts : EIT_Image_Availability_Coordinator.ImageFacts.Type,
                          reviewFacts : EIT_Image_Availability_Coordinator.ReviewFacts.Type,
                          contextFacts : EIT_Image_Availability_Coordinator.ContextFacts.Type,
                          serviceFacts : EIT_Image_Availability_Coordinator.ServiceFacts.Type): Unit = {
    put_imageFacts(imageFacts)
    put_reviewFacts(reviewFacts)
    put_contextFacts(contextFacts)
    put_serviceFacts(serviceFacts)
  }


  /** helper function to check FaultComposition_coordination_fault_composition's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param faultSummary method that will be called with the value of the outgoing data
   *        port 'faultSummary'.
   */
  def check_concrete_output(faultSummary: EIT_Image_Availability_Coordinator.FaultSummary => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val faultSummaryValue: EIT_Image_Availability_Coordinator.FaultSummary = get_faultSummary().get
    if(!faultSummary(faultSummaryValue)) {
      testFailures = testFailures :+ st"'faultSummary' did not match expected: value of the outgoing data port is ${faultSummaryValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_imageFacts(value : EIT_Image_Availability_Coordinator.ImageFacts.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_fault_composition.operational_api.imageFacts_Id, EIT_Image_Availability_Coordinator.ImageFacts_Payload(value))
  }

  // setter for in DataPort
  def put_reviewFacts(value : EIT_Image_Availability_Coordinator.ReviewFacts.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_fault_composition.operational_api.reviewFacts_Id, EIT_Image_Availability_Coordinator.ReviewFacts_Payload(value))
  }

  // setter for in DataPort
  def put_contextFacts(value : EIT_Image_Availability_Coordinator.ContextFacts.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_fault_composition.operational_api.contextFacts_Id, EIT_Image_Availability_Coordinator.ContextFacts_Payload(value))
  }

  // setter for in DataPort
  def put_serviceFacts(value : EIT_Image_Availability_Coordinator.ServiceFacts.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_fault_composition.operational_api.serviceFacts_Id, EIT_Image_Availability_Coordinator.ServiceFacts_Payload(value))
  }

  // getter for out DataPort
  def get_faultSummary(): Option[EIT_Image_Availability_Coordinator.FaultSummary] = {
    val value: Option[EIT_Image_Availability_Coordinator.FaultSummary] = get_faultSummary_payload() match {
      case Some(EIT_Image_Availability_Coordinator.FaultSummary_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port faultSummary.  Expecting 'EIT_Image_Availability_Coordinator.FaultSummary_Payload' but received ${v}")
      case _ => None[EIT_Image_Availability_Coordinator.FaultSummary]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_faultSummary_payload(): Option[EIT_Image_Availability_Coordinator.FaultSummary_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_fault_composition.initialization_api.faultSummary_Id).asInstanceOf[Option[EIT_Image_Availability_Coordinator.FaultSummary_Payload]]
  }

}
